-- ===========================================================================
-- Seed 16 : quizzes for the PHP course
--
-- One per level. The scratchpad on each quiz page opens on a PHP starter,
-- because starter_for_course() reads the course slug - so a learner unsure of
-- an answer can run the snippet rather than argue with themselves about it.
--
-- Generated by scratchpad/gen/build_php_quizzes.py, which also checks that every
-- single_choice has exactly one correct option and every multiple_choice has
-- at least two. A quiz that cannot be passed is not obvious from the SQL.
-- ===========================================================================

INSERT INTO assessment_quizzes
  (id, course_id, lesson_id, title, description, pass_percent, time_limit_seconds,
   max_attempts, shuffle_questions, shuffle_options, show_answers, status)
VALUES
  ('f0000001-0000-4000-8000-000000000018',
   'c0000001-0000-4000-8000-000000000009', 'e0000001-0000-4000-8000-000000000079',
   'Level 1 Check: Types, Flow and Arrays',
   'Comparison, control flow and the array type. Every one of these can be settled in the scratchpad below the questions.',
   60, 600, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-000000000019',
   'c0000001-0000-4000-8000-000000000009', 'e0000001-0000-4000-8000-00000000007a',
   'Level 2 Check: Text, Classes and Failure',
   'Strings and dates, the class machinery, and the difference between an Error and an Exception.',
   60, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000001a',
   'c0000001-0000-4000-8000-000000000009', 'e0000001-0000-4000-8000-00000000007b',
   'Level 3 Check: Composition, Laziness and Safety',
   'Traits, static state, generators, and the three mistakes that become vulnerabilities.',
   70, 720, NULL, 0, 1, 1, 'published'),

  ('f0000001-0000-4000-8000-00000000001b',
   'c0000001-0000-4000-8000-000000000009', 'e0000001-0000-4000-8000-00000000007c',
   'Expert Exam: PHP',
   'Attributes and reflection, where the time goes, and how an application is arranged.',
   70, 1500, 3, 1, 1, 1, 'published')
ON DUPLICATE KEY UPDATE
  title = VALUES(title), description = VALUES(description),
  pass_percent = VALUES(pass_percent), status = VALUES(status);

INSERT INTO assessment_questions
  (id, quiz_id, kind, prompt, explanation, points, `position`, correct_text)
VALUES
  -- Level 1 Check: Types, Flow and Arrays
  ('a1000001-0000-4000-8000-000000000241', 'f0000001-0000-4000-8000-000000000018', 'single_choice',
   'What is the difference between == and === in PHP?',
   '== converts the operands to a common type before comparing; === compares type and value with no conversion. Prefer === unless you have a specific reason, because the conversion rules have exceptions you will not remember.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000242', 'f0000001-0000-4000-8000-000000000018', 'single_choice',
   'In PHP 8, what does "abc" == 0 evaluate to?',
   'false. Before PHP 8 the string was converted to a number, giving 0, and this was true - the single most-reported surprise in the language. PHP 8 compares a non-numeric string with a number as strings instead.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000243', 'f0000001-0000-4000-8000-000000000018', 'multiple_choice',
   'Which statements about match are true, compared with switch? Select all that apply.',
   'match compares with ===, is an expression so it returns a value, and throws UnhandledMatchError when nothing matches instead of falling through silently. It does not need break - cases do not fall through at all.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000244', 'f0000001-0000-4000-8000-000000000018', 'true_false',
   '$b = $a on an array makes $b a reference to $a, so changing $b changes $a.',
   'It does not. Arrays are assigned by value in PHP - $b is a copy. Objects are the exception: an object variable holds a handle, so a copy of it still points at the same object.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000245', 'f0000001-0000-4000-8000-000000000018', 'short_text',
   'Which function tells you whether an array''s keys are 0, 1, 2... in order - the thing json_encode uses to decide between a JSON array and a JSON object? Give the function name only.',
   'array_is_list. It is why array_filter often needs array_values after it: filter preserves keys, so a filtered list can encode as an object instead of an array.',
   2, 5, 'array_is_list'),

  -- Level 2 Check: Text, Classes and Failure
  ('a1000001-0000-4000-8000-000000000251', 'f0000001-0000-4000-8000-000000000019', 'single_choice',
   'strlen("héllo") returns 6 but the word has five characters. Why?',
   'A PHP string is a sequence of bytes, and the e-acute takes two of them in UTF-8. strlen counts bytes. Counting characters needs something that knows the encoding - mb_strlen on a normal server.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000252', 'f0000001-0000-4000-8000-000000000019', 'single_choice',
   'Why prefer DateTimeImmutable over DateTime?',
   'DateTime::modify changes the object in place, so a date handed to a function can come back different - and a date stored on another object can change underneath it. DateTimeImmutable returns a new instance instead.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000253', 'f0000001-0000-4000-8000-000000000019', 'multiple_choice',
   'Which of these are true of a readonly promoted property? Select all that apply.',
   'It is declared, typed and assigned in the constructor signature; it can be written once, from inside the class; and writing it afterwards is an Error. It does not make the object deeply immutable - a mutable object it points at can still change.',
   3, 3, NULL),

  ('a1000001-0000-4000-8000-000000000254', 'f0000001-0000-4000-8000-000000000019', 'single_choice',
   'What is the difference between Error and Exception in PHP?',
   'Both implement Throwable. Error means something is wrong with the program - a TypeError, a DivisionByZeroError. Exception means something is wrong with the situation, and is what your own classes extend. Catching Throwable catches both.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000255', 'f0000001-0000-4000-8000-000000000019', 'true_false',
   '$value = @$data["missing"] and $value = $data["missing"] ?? null do the same thing.',
   'They do not, though both avoid a warning. @ suppresses the diagnostic and hides any other problem on that line too. ?? states a default explicitly and suppresses nothing - it is what you meant, and it stays readable.',
   2, 5, NULL),

  -- Level 3 Check: Composition, Laziness and Safety
  ('a1000001-0000-4000-8000-000000000261', 'f0000001-0000-4000-8000-00000000001a', 'single_choice',
   'Two traits used by the same class both define speak(). What happens?',
   'A fatal error, unless you resolve it with insteadof - and optionally alias the other one with as. PHP will not pick for you, which is the right call: silently choosing one would be a bug you could not see.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000262', 'f0000001-0000-4000-8000-00000000001a', 'single_choice',
   'What is the difference between self:: and static:: inside a parent class?',
   'self:: is fixed to the class the code was written in. static:: resolves to the class that was actually called - late static binding - which is what makes new static() return the subclass rather than the parent.',
   2, 2, NULL),

  ('a1000001-0000-4000-8000-000000000263', 'f0000001-0000-4000-8000-00000000001a', 'single_choice',
   'A function contains yield. What happens when you call it?',
   'Nothing in the body runs. Calling it returns a Generator; the body executes only when something iterates, and pauses again at each yield. That is what lets a generator describe an endless sequence or read a file larger than memory.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000264', 'f0000001-0000-4000-8000-00000000001a', 'multiple_choice',
   'Which of these actually prevent SQL injection? Select all that apply.',
   'Only parameters do. A prepared statement sends the query and the values separately, so a value can never be read as syntax. Escaping functions are a weaker, easier-to-get-wrong version of the same idea; checking for keywords is not a defence at all, and htmlspecialchars is for output, not for queries.',
   3, 4, NULL),

  ('a1000001-0000-4000-8000-000000000265', 'f0000001-0000-4000-8000-00000000001a', 'true_false',
   'Escaping input as it arrives, once, keeps it safe wherever it is later used.',
   'It does not. Escaping depends on the destination: what is correct for HTML is wrong in a URL, and both are wrong in SQL. Escape at the point of output, for the context it is going into - and store the original.',
   2, 5, NULL),

  -- Expert Exam: PHP
  ('a1000001-0000-4000-8000-000000000271', 'f0000001-0000-4000-8000-00000000001b', 'single_choice',
   'What does a PHP attribute do on its own?',
   'Nothing. An attribute is inert metadata attached to a declaration; it has an effect only when something reflects over it and acts. That is exactly why adding one is safe - and why a typo in an attribute can be silently ignored.',
   2, 1, NULL),

  ('a1000001-0000-4000-8000-000000000272', 'f0000001-0000-4000-8000-00000000001b', 'multiple_choice',
   'What are the real costs of reflection? Select all that apply.',
   'It is slower than a direct call, it is invisible to static analysis and to an IDE, and it can reach private state and so bypass the guarantees a class makes. It is not deprecated - frameworks rely on it, and pay the cost once at boot rather than in a loop.',
   3, 2, NULL),

  ('a1000001-0000-4000-8000-000000000273', 'f0000001-0000-4000-8000-00000000001b', 'single_choice',
   'A page runs one query to fetch 50 rows, then one more query per row. What is this, and what fixes it?',
   'The N+1 query problem, and the fix is to fetch the related rows in one further query keyed by id - not to make the loop faster. Fifty round trips cost fifty latencies, and no amount of micro-optimisation inside the loop recovers them.',
   2, 3, NULL),

  ('a1000001-0000-4000-8000-000000000274', 'f0000001-0000-4000-8000-00000000001b', 'single_choice',
   'Why is static state hard to test?',
   'It survives between calls and cannot be replaced, so one test leaks into the next and there is no way to substitute a double. An injected dependency is visible in the signature and can be swapped - which is the whole argument for composition.',
   2, 4, NULL),

  ('a1000001-0000-4000-8000-000000000275', 'f0000001-0000-4000-8000-00000000001b', 'true_false',
   'In a well-structured application, the domain classes should depend on the database layer.',
   'The dependency points the other way. The domain owns the interface it needs, and the database implementation depends on the domain to satisfy it. That is what lets the rules be tested with no setup, and what keeps swapping the storage a local change.',
   2, 5, NULL)
ON DUPLICATE KEY UPDATE
  prompt = VALUES(prompt), explanation = VALUES(explanation),
  points = VALUES(points), correct_text = VALUES(correct_text);

DELETE FROM assessment_question_options
 WHERE question_id IN (
   SELECT id FROM assessment_questions
    WHERE quiz_id IN ('f0000001-0000-4000-8000-000000000018',
                      'f0000001-0000-4000-8000-000000000019',
                      'f0000001-0000-4000-8000-00000000001a',
                      'f0000001-0000-4000-8000-00000000001b'));

INSERT INTO assessment_question_options (question_id, body, is_correct, `position`)
SELECT v.question_id, v.body, v.is_correct, v.pos
  FROM (
    SELECT 'a1000001-0000-4000-8000-000000000241' AS question_id, '== converts before comparing; === does not' AS body, 1 AS is_correct, 1 AS pos
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000241', '=== is faster but otherwise identical', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000241', '== is for numbers and === is for strings', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000241', '=== compares object identity only', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000242', 'false - PHP 8 changed this comparison', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000242', 'true, as it always has been', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000242', 'It raises a TypeError', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000242', 'It depends on strict_types', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000243', 'It compares strictly, with ===', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000243', 'It is an expression and returns a value', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000243', 'An unmatched value throws rather than being ignored', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000243', 'It still needs break to stop fall-through', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000244', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000244', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000251', 'strlen counts bytes, and the accented character takes two', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000251', 'strlen counts the terminating null byte', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000251', 'The string is stored as UTF-16', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000251', 'It is a bug fixed in PHP 8', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000252', 'DateTime mutates in place, so a date passed elsewhere can change underneath you', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000252', 'DateTimeImmutable is faster', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000252', 'DateTime cannot handle time zones', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000252', 'DateTime is deprecated', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000253', 'It is declared and assigned in the constructor signature', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000253', 'Assigning it after construction throws an Error', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000253', 'It can be initialised once, from inside the class', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000253', 'It makes everything the object references immutable too', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000254', 'Error means the program is wrong; Exception means the situation is', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000254', 'Error cannot be caught at all', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000254', 'Exception is for fatal problems and Error is for warnings', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000254', 'They are aliases of each other', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000255', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000255', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000261', 'A fatal error unless insteadof resolves it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000261', 'The first trait listed wins', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000261', 'The last trait listed wins', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000261', 'Both run, in order', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000262', 'static:: resolves to the called class; self:: is fixed where it was written', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000262', 'They are identical', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000262', 'self:: is for properties and static:: for methods', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000262', 'static:: only works inside a static method', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000263', 'It returns a Generator without running any of the body', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000263', 'It runs the whole body and returns an array', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000263', 'It runs to the first yield and returns that value', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000263', 'It is a syntax error outside a loop', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000264', 'A prepared statement with bound parameters', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000264', 'Passing values as parameters rather than concatenating them', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000264', 'Never building a query by joining strings', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000264', 'Rejecting any input containing the word SELECT', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000265', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000265', 'False', 1, 2

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000271', 'Nothing until something reflects over it', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000271', 'It runs when the class is loaded', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000271', 'It is checked by the compiler like a type', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000271', 'It is a comment the engine ignores entirely', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000272', 'It is slower than calling directly', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000272', 'Static analysis and IDEs cannot follow it', 1, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000272', 'It can reach private state and bypass a class''s guarantees', 1, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000272', 'It is deprecated in modern PHP', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000273', 'N+1 queries - batch the related rows into one query', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000273', 'A memory leak - free each row after use', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000273', 'Normal, as long as each query is indexed', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000273', 'A caching problem - add a cache in front of it', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000274', 'It persists between calls and cannot be substituted', 1, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000274', 'It is slower than instance state', 0, 2
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000274', 'It cannot be typed', 0, 3
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000274', 'PHP forbids static properties in tests', 0, 4

    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000275', 'True', 0, 1
    UNION ALL SELECT 'a1000001-0000-4000-8000-000000000275', 'False', 1, 2
  ) v;

CALL catalog_refresh_course_rollup('c0000001-0000-4000-8000-000000000009');
